function kClosest(points, k) {
  const dist = ([x, y]) => x * x + y * y;    // squared distance: no square root needed
  return [...points].sort((a, b) => dist(a) - dist(b)).slice(0, k);
}

int[][] kClosest(int[][] points, int k) {
    int[][] sorted = points.clone();
    Arrays.sort(sorted, (a, b) -> Integer.compare(dist(a), dist(b)));    // closest first
    return Arrays.copyOf(sorted, k);
}

int dist(int[] p) {
    return p[0] * p[0] + p[1] * p[1];        // squared distance: no square root needed
}

vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {
    auto dist = [](const vector<int>& p) { return p[0] * p[0] + p[1] * p[1]; };
    vector<vector<int>> sorted = points;
    sort(sorted.begin(), sorted.end(), [&](const auto& a, const auto& b) { return dist(a) < dist(b); });
    return vector<vector<int>>(sorted.begin(), sorted.begin() + k);   // the k closest
}

function kClosest(points, k) {
  const dist = ([x, y]) => x * x + y * y;
  const heap = Heap.from(points, (a, b) => dist(a) - dist(b));   // closest on top, built in O(n)
  const out = [];
  for (let i = 0; i < k; i++) out.push(heap.pop());               // the k closest, in order
  return out;
}

int[][] kClosest(int[][] points, int k) {
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(dist(a), dist(b)));
    for (int[] p : points) heap.offer(p);          // closest on top
    int[][] out = new int[k][];
    for (int i = 0; i < k; i++) out[i] = heap.poll();
    return out;
}

