vector<vector<int>> kClosest(vector<vector<int>>& points, int k) {
    // (squared distance, index) with greater<>: a min-heap, closest on top
    vector<pair<int, int>> items;
    for (int i = 0; i < (int)points.size(); i++)
        items.push_back({points[i][0] * points[i][0] + points[i][1] * points[i][1], i});
    priority_queue<pair<int, int>, vector<pair<int, int>>, greater<>> heap(items.begin(), items.end());
    vector<vector<int>> out;
    for (int i = 0; i < k; i++) {
        out.push_back(points[heap.top().second]);
        heap.pop();
    }
    return out;
}

function kClosest(points, k) {
  const dist = ([x, y]) => x * x + y * y;            // squared distance: no square root needed
  const heap = new Heap((a, b) => dist(b) - dist(a)); // a max-heap: the farthest kept point on top
  for (const p of points) {
    heap.push(p);
    if (heap.size() > k) heap.pop();                 // drop the farthest: not among the k closest
  }
  return heap.items;
}

import heapq

def k_closest(points, k):
    heap = []                                   # (-distance, x, y): a max-heap by distance
    for x, y in points:
        heapq.heappush(heap, (-(x * x + y * y), x, y))
        if len(heap) > k:
            heapq.heappop(heap)                 # drop the farthest: not among the k closest
    return [[x, y] for _, x, y in heap]

int[][] kClosest(int[][] points, int k) {
    // a max-heap by squared distance: the farthest kept point on top
    PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> Integer.compare(dist(b), dist(a)));
    for (int[] p : points) {
        heap.offer(p);
        if (heap.size() > k) heap.poll();       // drop the farthest: not among the k closest
    }
    return heap.toArray(new int[0][]);
}

